270	///   `{"text": <the output string>, "final_message": <the same final output string>,
271	///   "stop_reason": "end_turn", "session_id": <the envelope's own id>}` (the envelope protocol
272	///   defines `output` as the final value; its `stop.reason` is mapped through the neutral vocabulary),
273	/// - `stop.reason == "completed"` with a non-String `output` → [`HarnessError::Contract`]
274	///   naming the canonical agent-outcome contract and what was found — a typed, DETERMINISTIC
275	///   contract refusal at this boundary (terminal in the worker's mapping), never a
276	///   workflow-side serde decode error,
277	/// - any other `stop.reason` → [`HarnessError::Harness`] carrying the whole `stop` object
278	///   (reason plus per-variant detail) verbatim — and the partial `output`, when the envelope
279	///   carried one — so the caller can judge retry (or accept the partial),
280	/// - a `null` result (a prompt that resolved entirely to a local slash command) →
281	///   [`HarnessError::Harness`] — an agent activity must produce output,
282	/// - a result-less, error-less Response (a broken peer) → [`HarnessError::Protocol`],
283	/// - a non-envelope result → [`HarnessError::Protocol`] naming what was missing.
284	///
285	/// A provider policy refusal is recognised here, while the JSON-RPC error is
286	/// still structured. The exact `/error/code` data path is preferred; because
287	/// today's norn output drops that provider code, the measured adapter-owned
288	/// message phrase is the deliberately narrow textual fallback. Other error
289	/// objects surface as [`HarnessError::Harness`].
290	fn response_into_payload(response: JsonRpcResponse) -> Result<Payload, HarnessError> {
291	    if let Some(error) = response.error {
292	        let detail = format!(
293	            "run/execute failed (code {}): {}",
294	            error.code, error.message
295	        );
296	        if let Some(detection) = policy_refusal_detection(&error) {
297	            return Err(HarnessError::policy_refused(detail, detection));
298	        }
299	        return Err(HarnessError::harness(detail));
300	    }
301	    // The envelope type keeps key presence: `None` means the frame carried NO `result` key — with
302	    // `error` also absent that is a broken peer, not a payload. A PRESENT `"result": null`
303	    // (`Some(Value::Null)`) is the contract's answer for a prompt that resolved entirely to a
304	    // local slash command.
305	    let result = match response.result {
306	        None => {
307	            return Err(HarnessError::protocol(
308	                "run/execute response carried neither result nor error",
309	            ));
310	        }
311	        Some(serde_json::Value::Null) => {
312	            return Err(HarnessError::harness(
313	                "run resolved to a local slash command; no output",
314	            ));
315	        }
316	        Some(result) => result,
317	    };
318	    translate::run_result_to_outcome(&result)?
319	        .into_payload()
320	        .map_err(|source| HarnessError::protocol(format!("run output is not encodable: {source}")))
321	}
