326	fn policy_refusal_detection(
327	    error: &aion_integrations::jsonrpc::JsonRpcError,
328	) -> Option<PolicyRefusalDetection> {
329	    let structured = error.data.as_ref().and_then(|data| {
330	        data.pointer("/error/code")
331	            .and_then(serde_json::Value::as_str)
332	    });
333	    if structured == Some(POLICY_REFUSAL_CODE) {
334	        Some(PolicyRefusalDetection::Structured)
335	    } else if error.message.contains(POLICY_REFUSAL_MESSAGE) {
336	        Some(PolicyRefusalDetection::Textual)
337	    } else {
338	        None
339	    }
340	}
