342	impl<R, W> Drop for NornSession<R, W> {
343	    fn drop(&mut self) {
344	        // Abort the pump and reap the child so a dropped session never leaks a task or a process.
345	        if let Some(pump) = self.pump.take() {
346	            pump.abort();
347	        }
348	        if let Some(mut child) = self.child.take() {
349	            // A best-effort kill; the child may already have exited.
350	            let _ = child.start_kill();
351	        }
352	    }
353	}
