110	/// Interprets the terminal outcome as the activity's [`Payload`], or the honest error it is.
111	///
112	/// - **`end_turn`** → the completed run. The payload is the canonical [`AgentOutcome`] record,
113	///   `{"text": <all completed answers>, "final_message": <the last completed answer>,
114	///   "stop_reason": "end_turn", "session_id": <the ACP session>}` —
115	///   ACP's native stop reason mapped through the adapter's existing neutral
116	///   [`translate::stop_kind`] mapping and spelled by the one canonical
117	///   [`StopKind::canonical_stop_reason`](aion_integrations::StopKind::canonical_stop_reason)
118	///   vocabulary, and the session the agent itself minted (or reloaded) as the record's
119	///   conversation handle. ACP's Response carries ONLY a stop reason, so the answer itself has to
120	///   come from the accumulated `agent_message_chunk` text; a payload of the stop reason alone
121	///   would hand the workflow an activity result with no result in it.
122	/// - **`refusal`** → [`HarnessError::PolicyRefused`].
123	/// - **`max_tokens`, `max_turn_requests`** → [`HarnessError::Harness`] naming the reason.
124	///   None is a completed run: the agent stopped short. The partial text rides along,
125	///   labelled and bounded, so a caller's accept-the-partial policy stays reachable.
126	/// - **`cancelled`** → [`HarnessError::Harness`] whose message starts with
127	///   [`protocol::CANCELLED_DETAIL_PREFIX`], so a cancellation is distinguishable from a failure.
128	/// - an **error Response** → [`HarnessError::Harness`]; code `-32000` names the authentication the
129	///   agent is demanding, and `-32800` is reported as a cancellation.
130	/// - a Response with **neither** `result` nor `error` → [`HarnessError::Protocol`]. A broken frame.
131	pub(crate) fn outcome_into_payload(
132	    outcome: PromptOutcome,
133	    session_id: &SessionId,
134	) -> Result<Payload, HarnessError> {
135	    let PromptOutcome {
136	        response,
137	        text,
138	        final_message,
139	    } = outcome;
140	    if let Some(error) = response.error {
141	        return Err(prompt_error(&error, &text));
142	    }
143	    let Some(result) = response.result else {
144	        return Err(HarnessError::protocol(
145	            "the session/prompt response carried neither result nor error",
146	        ));
147	    };
148	    let prompt: PromptResponse = serde_json::from_value(result.clone()).map_err(|source| {
149	        HarnessError::protocol(format!(
150	            "the session/prompt result is not an ACP PromptResponse ({source}): {result}"
151	        ))
152	    })?;
153	    let label = translate::stop_reason_label(prompt.stop_reason);
154	    if !translate::is_success(prompt.stop_reason) {
155	        if matches!(prompt.stop_reason, StopReason::Refusal) {
156	            return Err(policy_refusal(label, &text));
157	        }
158	        return Err(non_completion(prompt.stop_reason, label, &text));
159	    }
160	    AgentOutcome::new(
161	        text,
162	        final_message,
163	        &translate::stop_kind(prompt.stop_reason),
164	        session_id.to_string(),
165	    )
166	    .into_payload()
167	    .map_err(|source| {
168	        HarnessError::protocol(format!("the terminal payload is not encodable: {source}"))
169	    })
170	}
