182	/// The honest error for a turn that ended on a stop reason other than `end_turn`.
183	fn non_completion(reason: StopReason, label: &str, text: &str) -> HarnessError {
184	    let mut message = if matches!(reason, StopReason::Cancelled) {
185	        format!("{}: stopReason: {label}", protocol::CANCELLED_DETAIL_PREFIX)
186	    } else {
187	        format!("the prompt turn did not complete: stopReason: {label}")
188	    };
189	    append_partial(&mut message, text);
190	    HarnessError::harness(message)
191	}
