193	/// The honest error for a `session/prompt` answered with a JSON-RPC error object.
194	fn prompt_error(error: &JsonRpcError, text: &str) -> HarnessError {
195	    let mut message = if error.code == protocol::auth_required_code() {
196	        format!(
197	            "the agent requires authentication before it will run (code {}): {} — an unattended \
198	             activity cannot complete an interactive `authenticate` flow; configure the agent's \
199	             credentials in the harness environment",
200	            error.code, error.message
201	        )
202	    } else if error.code == protocol::request_cancelled_code() {
203	        format!(
204	            "{}: the agent answered session/prompt with code {} ({}) instead of \
205	             stopReason `cancelled`",
206	            protocol::CANCELLED_DETAIL_PREFIX,
207	            error.code,
208	            error.message
209	        )
210	    } else {
211	        format!(
212	            "session/prompt failed (code {}): {}",
213	            error.code, error.message
214	        )
215	    };
216	    append_partial(&mut message, text);
217	    HarnessError::harness(message)
218	}
