220	/// Appends the turn's partial text to a failure message, labelled and bounded.
221	///
222	/// Nothing is appended for an empty partial: fabricating a `partial output:` label for text that does
223	/// not exist would read as though the agent had produced something.
224	fn append_partial(message: &mut String, text: &str) {
225	    if text.is_empty() {
226	        return;
227	    }
228	    message.push_str("; partial output: ");
229	    message.push_str(&bounded_for_message(text));
230	}
