232	/// Bounds `rendered` to [`PARTIAL_TEXT_MESSAGE_BYTES`], appending an explicit truncation marker when
233	/// it was cut. The cut lands on a char boundary so the message stays valid UTF-8.
234	fn bounded_for_message(rendered: &str) -> String {
235	    if rendered.len() <= PARTIAL_TEXT_MESSAGE_BYTES {
236	        return rendered.to_owned();
237	    }
238	    let mut end = PARTIAL_TEXT_MESSAGE_BYTES;
239	    while !rendered.is_char_boundary(end) {
240	        end -= 1;
241	    }
242	    format!(
243	        "{}… [partial output truncated for this message: {} of {} bytes shown]",
244	        &rendered[..end],
245	        end,
246	        rendered.len()
247	    )
248	}
